svg.script:
// ==================== VARIÁVEIS DE FÍSICA ====================
var massa = 1.0;
var g = 9.8;
var escala = 40;
var chao_y_svg = 420;
var v0_vertical = Math.sqrt(2 * 9.8 * 2);
var v0_horizontal = 1.0;

var restituicao_base = 0.75;
var atrito_quique_base = 0.85;
var mu_rolamento = 0.5;

var setaDireitaPressionada = false;

// Elementos
var bola = document.getElementById('bola');
var sombra = document.getElementById('sombra');
var trajetoriaPath = document.getElementById('trajetoriaPath');
var reguaDinamica = document.getElementById('reguaDinamica');
var nuvensContainer = document.getElementById('nuvensContainer');
var linhasPerspectiva = document.getElementById('linhasPerspectiva');
var massaDisplay = document.getElementById('massaDisplay');
var gravDisplay = document.getElementById('gravDisplay');
var v0yDisplay = document.getElementById('v0yDisplay');
var v0xDisplay = document.getElementById('v0xDisplay');
var massaInput = document.getElementById('massaInput');
var gravInput = document.getElementById('gravInput');
var v0yInput = document.getElementById('v0yInput');
var v0xInput = document.getElementById('v0xInput');
var svgRaiz = document.getElementById('svgRaiz');

// Estado da simulação
var pos_x_real = 0.0;
var pos_y_real = 0.0;
var v_x = 0.0;
var v_y = 0.0;
var animando = false;
var ultimaTimestamp = null;
var acumuladorTempo = 0;
var passoFisica = 1/120;

// Câmera
var cameraX_m = 0.0;
var cameraSmoothness = 0.08;

// Trajetória
var pontosTrajetoria = [];
var contadorPassos = 0;
var trajetoriaAtiva = true;

// ========== NUVENS DINÂMICAS ==========
var nuvens = [];
var numNuvens = 14;
var paralaxeFator = 0.6;

function inicializarNuvens() {
  nuvens = [];
  for (var i = 0; i < numNuvens; i++) {
    nuvens.push({
      posX: (Math.random() - 0.5) * 30,
      posY: 40 + Math.random() * 200,
      scale: 0.6 + Math.random() * 0.8,
      opacity: 0.7 + Math.random() * 0.3
    });
  }
}

function atualizarNuvens() {
  nuvensContainer.innerHTML = '';
  var ns = 'http://www.w3.org/2000/svg';
  for (var i = 0; i < nuvens.length; i++) {
    var n = nuvens[i];
    var x_tela = 400 + (n.posX - cameraX_m * paralaxeFator) * escala;

    if (x_tela < -200) {
      n.posX = cameraX_m * paralaxeFator + (800 + 150 + Math.random() * 200) / escala;
      x_tela = 400 + (n.posX - cameraX_m * paralaxeFator) * escala;
    } else if (x_tela > 1000) {
      n.posX = cameraX_m * paralaxeFator - (800 + 150 + Math.random() * 200) / escala;
      x_tela = 400 + (n.posX - cameraX_m * paralaxeFator) * escala;
    }

    var use = document.createElementNS(ns, 'use');
    use.setAttribute('href', '#nuvemModelo');
    use.setAttribute('x', x_tela);
    use.setAttribute('y', n.posY);
    use.setAttribute('transform', 'scale(' + n.scale + ')');
    use.setAttribute('opacity', n.opacity);
    nuvensContainer.appendChild(use);
  }
}

// ========== LINHAS DE PERSPECTIVA DO CHÃO ==========
function atualizarLinhasPerspectiva() {
  linhasPerspectiva.innerHTML = '';
  var ns = 'http://www.w3.org/2000/svg';
  var inicio = cameraX_m - 10;
  var fim = cameraX_m + 10;
  var passo = 1.0;

  var fugaX = 400;
  var fugaY = 200;

  for (var m = Math.floor(inicio); m <= Math.ceil(fim); m += passo) {
    var x_chao = 400 + (m - cameraX_m) * escala;
    if (x_chao < -10 || x_chao > 810) continue;

    var line = document.createElementNS(ns, 'line');
    line.setAttribute('x1', x_chao);
    line.setAttribute('y1', chao_y_svg + 80);
    line.setAttribute('x2', fugaX);
    line.setAttribute('y2', fugaY);
    line.setAttribute('stroke', 'rgba(0,80,0,0.25)');
    line.setAttribute('stroke-width', '1.8');
    linhasPerspectiva.appendChild(line);
  }
}

// ========== FÍSICA ==========
function getRestituicao() {
  return restituicao_base / (1.0 + 0.5 * massa);
}
function getAtritoQuique() {
  return atrito_quique_base / (1.0 + 0.3 * massa);
}
function getAceleracaoRolamento() {
  return -mu_rolamento * g * (1.0 + 0.2 * massa);
}

function sincronizarInputs() {
  massaInput.value = massa.toFixed(1);
  gravInput.value = g.toFixed(1);
  v0yInput.value = v0_vertical.toFixed(2);
  v0xInput.value = v0_horizontal.toFixed(1);
  massaDisplay.textContent = massa.toFixed(1);
  gravDisplay.textContent = g.toFixed(1);
  v0yDisplay.textContent = v0_vertical.toFixed(2);
  v0xDisplay.textContent = v0_horizontal.toFixed(1);
}

window.atualizarMassa = function(valor) {
  var novo = parseFloat(valor);
  if (!isNaN(novo) && novo > 0) {
    massa = novo;
    massaDisplay.textContent = massa.toFixed(1);
  } else {
    massaInput.value = massa.toFixed(1);
  }
};
window.atualizarGravidade = function(valor) {
  var novo = parseFloat(valor);
  if (!isNaN(novo) && novo > 0) {
    g = novo;
    gravDisplay.textContent = g.toFixed(1);
  } else {
    gravInput.value = g.toFixed(1);
  }
};
window.atualizarV0y = function(valor) {
  var novo = parseFloat(valor);
  if (!isNaN(novo) && novo > 0) {
    v0_vertical = novo;
    v0yDisplay.textContent = v0_vertical.toFixed(2);
  } else {
    v0yInput.value = v0_vertical.toFixed(2);
  }
};
window.atualizarV0x = function(valor) {
  var novo = parseFloat(valor);
  if (!isNaN(novo) && novo >= 0) {
    v0_horizontal = novo;
    v0xDisplay.textContent = v0_horizontal.toFixed(1);
  } else {
    v0xInput.value = v0_horizontal.toFixed(1);
  }
};

window.toggleTrajetoria = function(checked) {
  trajetoriaAtiva = checked;
  trajetoriaPath.style.display = checked ? 'block' : 'none';
};

// ========== RÉGUA HORIZONTAL DINÂMICA ==========
function desenharRegua() {
  reguaDinamica.innerHTML = '';
  var inicio = cameraX_m - 5;
  var fim = cameraX_m + 5;
  var primeiroMetro = Math.floor(inicio);
  var ns = 'http://www.w3.org/2000/svg';
  for (var m = primeiroMetro; m <= fim; m++) {
    var x_tela = 400 + (m - cameraX_m) * escala;
    if (x_tela < 0 || x_tela > 800) continue;
    var line = document.createElementNS(ns, 'line');
    line.setAttribute('x1', x_tela);
    line.setAttribute('y1', chao_y_svg);
    line.setAttribute('x2', x_tela);
    line.setAttribute('y2', chao_y_svg - 10);
    line.setAttribute('stroke', '#333');
    line.setAttribute('stroke-width', '1.5');
    reguaDinamica.appendChild(line);
    var text = document.createElementNS(ns, 'text');
    text.setAttribute('x', x_tela);
    text.setAttribute('y', chao_y_svg - 15);
    text.setAttribute('font-family', 'Arial, sans-serif');
    text.setAttribute('font-size', '10');
    text.setAttribute('fill', '#333');
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('dominant-baseline', 'bottom');
    text.textContent = Math.round(m);
    reguaDinamica.appendChild(text);
  }
}

// ========== TRAJETÓRIA ==========
function limparTrajetoria() {
  pontosTrajetoria = [];
  trajetoriaPath.setAttribute('d', '');
}

function adicionarPontoTrajetoria() {
  if (!trajetoriaAtiva) return;
  if (pontosTrajetoria.length > 0) {
    var ultimo = pontosTrajetoria[pontosTrajetoria.length - 1];
    var dx = pos_x_real - ultimo.x;
    var dy = pos_y_real - ultimo.y;
    if (dx*dx + dy*dy < 0.01) return;
  }
  pontosTrajetoria.push({x: pos_x_real, y: pos_y_real});
  desenharTrajetoria();
}

function desenharTrajetoria() {
  if (pontosTrajetoria.length === 0) {
    trajetoriaPath.setAttribute('d', '');
    return;
  }
  var refX = pos_x_real;
  var d = '';
  for (var i = 0; i < pontosTrajetoria.length; i++) {
    var x_tela = 400 + (pontosTrajetoria[i].x - refX) * escala;
    var y_tela = chao_y_svg - pontosTrajetoria[i].y * escala;
    if (i === 0) d += 'M' + x_tela.toFixed(1) + ',' + y_tela.toFixed(1);
    else d += ' L' + x_tela.toFixed(1) + ',' + y_tela.toFixed(1);
  }
  trajetoriaPath.setAttribute('d', d);
}

// ========== ATUALIZAÇÃO DA CENA ==========
function atualizarCena() {
  var dx = pos_x_real - cameraX_m;
  cameraX_m += dx * cameraSmoothness;

  var y_svg = chao_y_svg - Math.min(pos_y_real * escala, 400);
  bola.setAttribute('cy', y_svg);
  sombra.setAttribute('cy', chao_y_svg);

  var alturaMaxRef = (g > 0) ? (v0_vertical * v0_vertical) / (2 * g) : 1.0;
  var fatorAltura = Math.min(pos_y_real / Math.max(alturaMaxRef, 0.1), 1.0);
  var rx_sombra = 20 - 15 * fatorAltura;
  sombra.setAttribute('rx', Math.max(rx_sombra, 3));
  sombra.setAttribute('opacity', Math.max(0.4 - 0.35 * fatorAltura, 0.05));

  desenharRegua();
  desenharTrajetoria();
  atualizarNuvens();
  atualizarLinhasPerspectiva();
}

// ========== SIMULAÇÃO ==========
function reset() {
  pos_x_real = 0.0;
  pos_y_real = 0.0;
  v_x = 0.0;
  v_y = 0.0;
  cameraX_m = 0.0;
  acumuladorTempo = 0;
  limparTrajetoria();
  atualizarCena();
}

function simularPassoFixo(deltaT) {
  var a_x = 0.0;
  var a_y = -g;
  v_x += a_x * deltaT;
  v_y += a_y * deltaT;
  pos_x_real += v_x * deltaT;
  pos_y_real += v_y * deltaT;

  if (pos_y_real <= 0.0) {
    pos_y_real = 0.0;
    v_y = -v_y * getRestituicao();
    v_x *= getAtritoQuique();
    if (Math.abs(v_y) < 0.2) v_y = 0.0;
  }

  if (pos_y_real <= 0.0 && v_y === 0.0 && Math.abs(v_x) > 0.01) {
    v_x += getAceleracaoRolamento() * deltaT;
    if (Math.abs(v_x) < 0.05) v_x = 0.0;
  }

  if (pos_y_real * escala > 400) {
    pos_y_real = 400 / escala;
    v_y = 0.0;
  }

  contadorPassos++;
  if (contadorPassos % 2 === 0) {
    adicionarPontoTrajetoria();
  }

  atualizarCena();
}

function animar(timestamp) {
  if (!animando) return;
  if (ultimaTimestamp === null) ultimaTimestamp = timestamp;
  var deltaReal = (timestamp - ultimaTimestamp) / 1000;
  ultimaTimestamp = timestamp;
  if (deltaReal > 0.1) deltaReal = 0.1;
  acumuladorTempo += deltaReal;
  while (acumuladorTempo >= passoFisica) {
    simularPassoFixo(passoFisica);
    acumuladorTempo -= passoFisica;
  }
  if (Math.abs(v_x) < 0.05 && Math.abs(v_y) < 0.05 && pos_y_real === 0.0) {
    animando = false;
    ultimaTimestamp = null;
    adicionarPontoTrajetoria();
    atualizarCena();
  } else {
    requestAnimationFrame(animar);
  }
}

function lancarBola() {
  if (animando) return;
  reset();
  v_y = v0_vertical;
  if (setaDireitaPressionada) {
    v_x = v0_horizontal;
  } else {
    v_x = 0.0;
  }
  animando = true;
  ultimaTimestamp = null;
  requestAnimationFrame(animar);
}

// ========== EVENTOS ==========
document.addEventListener('keydown', function(event) {
  var ativo = document.activeElement;
  if (ativo && ativo.tagName === 'INPUT') return;
  if (event.code === 'Space') {
    event.preventDefault();
    lancarBola();
  }
});
document.addEventListener('keydown', function(event) {
  if (event.key === 'ArrowRight') {
    event.preventDefault();
    setaDireitaPressionada = true;
  }
});
document.addEventListener('keyup', function(event) {
  if (event.key === 'ArrowRight') {
    event.preventDefault();
    setaDireitaPressionada = false;
  }
});

// ========== INICIALIZAÇÃO ==========
if (svgRaiz) {
  svgRaiz.focus();
  svgRaiz.addEventListener('click', () => svgRaiz.focus());
}
sincronizarInputs();
inicializarNuvens();
reset();
document.getElementById('mostrarTrajetoria').checked = true;
trajetoriaAtiva = true;
